public.deities old WHERE old.slug=x.slug OR old.name=x.name) ON CONFLICT (slug) DO UPDATE SET is_published=true RETURNING id) SELECT jsonb_build_object('new_lineages',(SELECT count(*) FROM lineage_upsert),'new_benefits',(SELECT count(*) FROM benefit_upsert),'new_deities',(SELECT count(*) FROM deity_upsert)) AS inserted;
